const { Card, Typography, Empty } = ctx.libs.antd;
const record = (await ctx.getVar('ctx.popup.record')) || {};
const name = String(record.name ?? '');
const id = record.id;
const url = id ? '/x/main/qr?class=' + id : '';

ctx.render(
  <Card size="small">
    {url ? (
      <iframe src={url} style={{ width: 500, height: 640, border: 0, display: 'block' }} title={name || 'qr'} />
    ) : (
      <Empty description="未找到班次" />
    )}
  </Card>
);
